 "content": "from collections import deque


def transform(grid):
    """Return a 3x3 solid patch in the color of the largest connected colored object."""
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    best_color, best_size = None, -1
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            size = 0
            while q:
                y, x = q.popleft()
                size += 1
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= yy < h and 0 <= xx < w and not seen[yy][xx] and grid[yy][xx] == color:
                        seen[yy][xx] = True
                        q.append((yy, xx))
            if size > best_size:
                best_color, best_size = color, size
    if best_color is None:
        raise ValueError("no non-background object")
    return [[best_color] * 3 for _ in range(3)]


